INSERT INTO `products` (`id`, `product_id`, `sku`, `name`, `short_name`, `category_id`, `category_name`, `price`, `original_price`, `discount`, `badge`, `rating`, `sold`, `stock`, `brand`, `description`, `seo_tags`, `shopee_url`, `tiktok_url`, `is_flash_sale`, `flash_sale_percent`, `is_active`, `created_at`, `updated_at`, `features_vn`, `features_en`, `footer_info`, `production_year`, `clearance_price`, `daily_sale_price`, `campaign_price`, `off_platform_price`, `warranty_data`, `youtube_url`, `origin`, `volume`, `ingredients`) VALUES (26, 'serum-rau-ma-phuc-hoi-da-cica-complex', 'TCPHD', 'Serum Rau Má Phục Hồi Da CICA COMPLEX SERUM GC NATURE Chiết Xuất Rau Má Giảm Kích Ứng cho Da Nhạy Cảm Hàn Quốc', NULL, NULL, 'Serum / Tinh chất đặc trị', 360000, 400000, 10, 'Best', '5', 215, 523, 'GC Nature', 'Serum Phục Hồi Da CICA COMPLEX SERUM Chiết Xuất Rau Má Dịu Da Giảm Kích Ứng cho Da Nhạy Cảm\n✨ Vì sao bạn sẽ thích?\nDa bạn dễ ửng đỏ, châm chích khi đổi thời tiết, hay nổi mụn ẩn vì hàng rào bảo vệ yếu? Cica Complex Serum đến từ Hàn Quốc chính là ""vệ sĩ"" dịu nhẹ mà làn da nhạy cảm đang cần. Kết cấu gel-serum xanh trong, mỏng nhẹ, thẩm thấu tức thì, để lại cảm giác mát lạnh, ẩm mượt và êm dịu ngay từ lần đầu sử dụng.\n\n✨ ƯU ĐIỂM NỔI BẬT\n🌿 Bộ tứ Rau Má vàng (Asiaticoside, Madecassoside, Axit Asiatic, Axit Madecassic) làm dịu nhanh vùng da kích ứng, đỏ rát.\n🌿 Chiết xuất Centella Asiatica + Keo Ong tăng cường hàng rào ẩm, hỗ trợ phục hồi da yếu sau mụn.\n💧 Niacinamide + Beta-Glucan giúp da sáng đều màu, mờ vết thâm sau mụn, se khít lỗ chân lông.\n💧 Sodium Hyaluronate + Panthenol + Allantoin cấp ẩm sâu, giữ da căng mọng suốt ngày dài.\n🍃 Bổ sung loạt chiết xuất thực vật: lô hội, tảo bẹ, hoa tím, rễ cây du, rễ khoai lang nuôi dưỡng và làm mát da.\n✅ Không cồn khô, không paraben, dịu nhẹ, an toàn cho da nhạy cảm, bà bầu có thể tham khảo.\n\n✨ THÔNG TIN THƯƠNG HIỆU\nGC Nature (GC 네이처) là thương hiệu mỹ phẩm đến từ Hàn Quốc, nổi tiếng với các dòng sản phẩm chăm sóc da chuyên sâu và công nghệ Hàn Quốc hiện đại. Các dòng sản phẩm đã bán chạy TOP đầu tại Hàn Quốc, trên Coupang, Olive Young, TOP tìm kiếm trên Naver, được cộng đồng nghệ sỹ Hàn Quốc dùng và feedback uy tín. Sản phẩm được sản xuất bởi CELLCOCO.CO.,LTD, được nhập khẩu và phân phối chính hãng độc quyền bởi GC Nature tại Việt Nam.\n\n✨ THÀNH PHẦN CHÍNH\nDipropylene glycol, glycerin, niacinamide, 1,2-hexanediol, dầu thầu dầu hydro hóa PEG-60, chlorphenesin, caprylyl glycol, carbomer, trietanolamine, panthenol, betaine, allantoin, adenosine, xanthan gum, disodium EDTA, hương thơm, butylene glycol, Natri hyaluronate, chiết xuất lá lô hội, chiết xuất tảo bẹ, chiết xuất hoa tím, chiết xuất rễ cây du, chiết xuất rễ khoai lang, beta-glucan, chiết xuất Centella Asiatica, số màu vàng 4, số màu xanh 1, chiết xuất keo ong, asiaticoside, axit asiatic, madecassoside, axit madecassic.\n\n✨ HƯỚNG DẪN SỬ DỤNG\nBước 1: Làm sạch da với sữa rửa mặt, sau đó cân bằng bằng toner.\nBước 2: Lấy 2-3 giọt serum, chấm đều lên 5 điểm: trán, mũi, cằm và hai má.\nBước 3: Vỗ nhẹ từ trong ra ngoài đến khi serum thẩm thấu hoàn toàn.\nBước 4: Tiếp tục với kem dưỡng ẩm, đừng quên kem chống nắng vào buổi sáng.\n👉 Dùng đều đặn 2 lần/ngày sáng - tối để cảm nhận da dịu, mềm mượt rõ rệt.\n\n✨ HƯỚNG DẪN BẢO QUẢN\nĐể nơi khô thoáng, tránh ánh nắng trực tiếp và nhiệt độ cao trên 30°C.\nĐậy kín nắp sau mỗi lần dùng để giữ trọn dưỡng chất.\nKhông dùng tay bẩn hoặc dụng cụ không sạch tiếp xúc trực tiếp với serum.\nĐể xa tầm tay trẻ em.\n\n\n#serumcica #cicacomplexserum #serumrauma #anely #anelycica #serumhanquoc #serumphuchoida #serumdanhaycam #serumcapam #serumlamdiu #serumgiamkichung #cicaserum #myphamhanquoc #serumduda #serumdumun #anelyserum #seumlanhtinh #serumcentella #rauma', '{"title":"Serum Rau Má Phục Hồi Da CICA COMPLEX SERUM GC NATURE Chiết Xuất Rau Má Giảm Kích Ứng cho Da Nhạy Cảm Hàn Quốc","desc":"Serum Rau Má Phục Hồi Da CICA COMPLEX SERUM GC NATURE Chiết Xuất Rau Má Giảm Kích Ứng cho Da Nhạy Cảm Hàn Quốc\\n🌿 Làm dịu nhanh vùng da kích ứng, đỏ rát nhờ sức mạnh từ Bộ tứ Rau Má vàng (Asiaticoside, Madecassoside, Axit Asiatic, Axit Madecassic).\\n🌿 Tăng cường hàng rào ẩm, hỗ trợ phục hồi da yếu sau mụn với sự kết hợp của Chiết xuất Centella Asiatica và Keo Ong.\\n💧 Giúp da sáng đều màu, mờ vết thâm sau mụn, se khít lỗ chân lông nhờ bộ đôi Niacinamide + Beta-Glucan.\\n💧 Cấp ẩm sâu, giữ da căng mọng suốt ngày dài với khả năng giữ nước tuyệt vời từ Sodium Hyaluronate + Panthenol + Allantoin.\\n🍃 Nuôi dưỡng và làm mát da nhờ được bổ sung loạt chiết xuất thực vật tự nhiên: lô hội, tảo bẹ, hoa tím, rễ cây du, rễ khoai lang.\\n✅ An toàn cho da nhạy cảm (bà bầu có thể tham khảo) vì bảng thành phần siêu dịu nhẹ, hoàn toàn không chứa cồn khô và không paraben.","keywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, tinhchatcica, tinhchatrauma, phuchoida, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicacomplex"}', 'https://s.shopee.vn/5VTJbcYtHN', 'https://vt.tiktok.com/ZS965wrq4NUJv-Ultvr/', 1, 2, 1, '2026-07-03 11:16:34', '2026-07-27 11:57:30', 'Serum Rau Má Phục Hồi Da CICA COMPLEX SERUM GC NATURE Chiết Xuất Rau Má Giảm Kích Ứng cho Da Nhạy Cảm Hàn Quốc\n🌿 Làm dịu nhanh vùng da kích ứng, đỏ rát nhờ sức mạnh từ Bộ tứ Rau Má vàng (Asiaticoside, Madecassoside, Axit Asiatic, Axit Madecassic).\n🌿 Tăng cường hàng rào ẩm, hỗ trợ phục hồi da yếu sau mụn với sự kết hợp của Chiết xuất Centella Asiatica và Keo Ong.\n💧 Giúp da sáng đều màu, mờ vết thâm sau mụn, se khít lỗ chân lông nhờ bộ đôi Niacinamide + Beta-Glucan.\n💧 Cấp ẩm sâu, giữ da căng mọng suốt ngày dài với khả năng giữ nước tuyệt vời từ Sodium Hyaluronate + Panthenol + Allantoin.\n🍃 Nuôi dưỡng và làm mát da nhờ được bổ sung loạt chiết xuất thực vật tự nhiên: lô hội, tảo bẹ, hoa tím, rễ cây du, rễ khoai lang.\n✅ An toàn cho da nhạy cảm (bà bầu có thể tham khảo) vì bảng thành phần siêu dịu nhẹ, hoàn toàn không chứa cồn khô và không paraben', 'Niacinamide, Panthenol, Adenosine, Sodium Hyaluronate, Beta-Glucan, Centella Asiatica Extract, Lactobacillus Ferment, Propolis Extract, Madecassoside, Asiaticoside.', NULL, 2026, 0, 360000, 0, 0, '', NULL, 'Hàn Quốc', '50ml', 'Water, Glycerin, Dipropylene Glycol, Glycereth-26, Niacinamide, Betaine, 1,2-Hexanediol, PEG-60 Hydrogenated Castor Oil, Chlorphenesin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Triethanolamine, Caprylyl Glycol, Panthenol, Xanthan Gum, Hydroxyethylcellulose, Allantoin, Adenosine, Disodium EDTA, Sodium Polyacrylate, Fragrance (Perfume/Parfum), Butylene Glycol, Sodium Hyaluronate, Viola Mandshurica Flower Extract, Ulmus Davidiana Root Extract, Laminaria Japonica Extract, Dioscorea Japonica Root Extract, Aloe Barbadensis Leaf Extract, Beta-Glucan, Centella Asiatica Extract, CI 19140, Punica Granatum Flower Extract, Prunus Mume Root Extract, Prunus Mume Flower Extract, Portulaca Oleracea Extract, Opuntia Ficus-Indica Stem Extract, Nelumbo Nucifera Flower Extract, Cucurbita Pepo (Pumpkin) Fruit Extract, Althaea Rosea Root Extract, Althaea Rosea Flower Extract, Nelumbo Nucifera Root Extract, Lactobacillus Ferment, CI 42090, Propolis Extract, Asiaticoside, Madecassoside, Madecassic Acid, Asiatic Acid.');
INSERT INTO `products` (`id`, `product_id`, `sku`, `name`, `short_name`, `category_id`, `category_name`, `price`, `original_price`, `discount`, `badge`, `rating`, `sold`, `stock`, `brand`, `description`, `seo_tags`, `shopee_url`, `tiktok_url`, `is_flash_sale`, `flash_sale_percent`, `is_active`, `created_at`, `updated_at`, `features_vn`, `features_en`, `footer_info`, `production_year`, `clearance_price`, `daily_sale_price`, `campaign_price`, `off_platform_price`, `warranty_data`, `youtube_url`, `origin`, `volume`, `ingredients`) VALUES (27, 'serum-cap-am-chuyen-sau-skin-balancing-hyaluronic', 'TCCA', 'Serum Cấp Ẩm Chuyên Sâu SKIN BALANCING HYALURONIC GC NATURE Cấp Nước Đa Tầng Căng Bóng Da Hàn Quốc', NULL, NULL, 'Serum / Tinh chất đặc trị', 360000, 400000, 10, 'Bestseller', '5', 261, 99, 'GC Nature', 'Serum Cấp Ẩm Chuyên Sâu CICA BALANCING HYALURONIC GC NATURE Cấp Nước Đa Tầng Căng Bóng Da\n✨ Vì sao bạn sẽ thích?\nDa khô căng, bong tróc, lớp trang điểm dễ mốc cám và xuống tông? Serum CICA BALANCING HYALURONIC là ""ly nước thần"" cho làn da thiếu ẩm, với 8 dạng Hyaluronic Acid phân tử khác nhau thẩm thấu sâu vào từng lớp biểu bì, khoá ẩm bền lâu suốt 24 giờ. Kết hợp Niacinamide, Panthenol cùng dịch ốc sên và chiết xuất thảo mộc Hàn Quốc, sản phẩm giúp da căng mọng, mềm mịn, sáng khoẻ rạng rỡ ngay từ những lần đầu dùng.\n\n✨ ƯU ĐIỂM NỔI BẬT\n🌿 Cấp nước đa tầng, da căng bóng tức thì nhờ 8 dạng Hyaluronic Acid\n🌿 Làm sáng đều màu, mờ vết thâm sạm nhờ Niacinamide\n🌿 Làm dịu da nhạy cảm, giảm mẩn đỏ nhờ Panthenol & Allantoin\n🌿 Phục hồi, làm mềm mượt bề mặt da nhờ tinh chất Ốc Sên Hàn Quốc Snail Filtrate\n🌿 Tăng độ đàn hồi, ngăn ngừa lão hoá sớm nhờ Beta-Glucan & Adenosine \n🌿 Nuôi dưỡng da từ sâu bên trong bởi 7 chiết xuất thảo dược Hàn (sắn dây, cỏ ba lá, lựu, đương quy…) \n🌿 Kết cấu lỏng nhẹ, thấm nhanh, không nhờn rít — phù hợp mọi loại da, kể cả da dầu mụn\n\n✨ THÔNG TIN THƯƠNG HIỆU\nGC Nature (GC 네이처) là thương hiệu mỹ phẩm đến từ Hàn Quốc, nổi tiếng với các dòng sản phẩm chăm sóc da chuyên sâu và công nghệ Hàn Quốc hiện đại. Các dòng sản phẩm đã bán chạy TOP đầu tại Hàn Quốc, trên Coupang, Olive Young, TOP tìm kiếm trên Naver, được cộng đồng nghệ sỹ Hàn Quốc dùng và feedback uy tín. Sản phẩm được sản xuất bởi CELLCOCO.CO.,LTD, được nhập khẩu và phân phối chính hãng độc quyền bởi GC Nature tại Việt Nam.\n\n✨ THÀNH PHẦN CHÍNH\nWater, Glycerin, Dipropylene Glycol, Glycereth-26, Niacinamide, Betaine, 1,2-Hexanediol, PEG-60 Hydrogenated Castor Oil, Chlorphenesin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Triethanolamine, Caprylyl Glycol, Panthenol, Xanthan Gum, Hydroxyethylcellulose, Fragrance, Allantoin, Adenosine, Disodium EDTA, Sodium Polyacrylate, Butylene Glycol, Sodium Hyaluronate, Snail Secretion Filtrate, Beta-Glucan, Pentylene Glycol, Soy Isoflavones, Pueraria Lobata Root Extract, Pueraria Mirifica Root Extract, Polygonum Cuspidatum Root Extract, Cimicifuga Racemosa Root Extract, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Trifolium Pratense (Clover) Flower Extract, Punica Granatum Fruit Extract, Angelica Polymorpha Sinensis Root Extract, CI 42090, Hyaluronic Acid, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Hydrolyzed Sodium Hyaluronate.\n\n✨ HƯỚNG DẪN SỬ DỤNG\nBước 1: Làm sạch da với sữa rửa mặt, cân bằng bằng toner \nBước 2: Lấy 2–3 giọt serum ra lòng bàn tay \nBước 3: Vỗ nhẹ đều khắp mặt và cổ, ưu tiên vùng khô \nBước 4: Đợi 30 giây rồi dùng tiếp kem dưỡng và kem chống nắng \n👉 Dùng đều đặn sáng và tối để cảm nhận làn da căng mịn rõ rệt\n\n✨ HƯỚNG DẪN BẢO QUẢN\n– Để nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp và nhiệt độ cao \n– Đậy kín nắp ngay sau khi sử dụng để giữ chất lượng tinh chất \n– Để xa tầm tay trẻ em \n– Ngưng dùng và rửa sạch với nước nếu xuất hiện dấu hiệu khó chịu\n\n#serumcapam #serumhyaluronic #cicabalancing #gcnature #serumhanquoc #serumcapnuoc #duongamchuyensau #serumdacangbong #myphamhan #seruminiacinamide #serumphucholi #skincarehanquoc #serumchodakho #hyaluronicacid', '{"title":"Serum Cấp Ẩm Chuyên Sâu SKIN BALANCING HYALURONIC GC NATURE Cấp Nước Đa Tầng Căng Bóng Da Hàn Quốc","desc":"Serum Cấp Ẩm Chuyên Sâu SKIN BALANCING HYALURONIC GC NATURE Cấp Nước Đa Tầng Căng Bóng Da Hàn Quốc\\n🌿 Làm sáng đều màu, mờ vết thâm sạm nhờ Niacinamide\\n🌿 Cấp nước đa tầng, da căng bóng tức thì nhờ 8 dạng Hyaluronic Acid\\n🌿 Làm dịu da nhạy cảm, giảm mẩn đỏ nhờ Panthenol & Allantoin\\n🌿 Phục hồi, làm mềm mượt bề mặt da nhờ tinh chất Ốc Sên Hàn Quốc Snail Filtrate\\n🌿 Tăng độ đàn hồi, ngăn ngừa lão hoá sớm nhờ Beta-Glucan & Adenosine \\n🌿 Nuôi dưỡng da từ sâu bên trong bởi 7 chiết xuất thảo dược Hàn (sắn dây, cỏ ba lá, lựu, đương quy…) \\n🌿 Kết cấu lỏng nhẹ, thấm nhanh, không nhờn rít — phù hợp mọi loại da, kể cả da dầu mụn","keywords":"serum cấp ẩm, serum HA, serum hyaluronic, cấp nước đa tầng, căng bóng da, serum GC nature, serum dưỡng ẩm, dưỡng ẩm sâu, tinh chất HA, tinh chất ốc sên, mỹ phẩm Hàn, da căng mọng, phục hồi da, cấp ẩm chuyên sâu, mờ thâm sạm, serum cấp ẩm chuyên sâu, serum hyaluronic acid Hàn Quốc, serum cấp nước đa tầng, serum căng bóng da mặt, tinh chất cấp ẩm GC nature, serum cho da khô bong tróc, serum phục hồi mờ thâm, tinh chất ốc sên dưỡng ẩm, serum HA căng bóng da, mỹ phẩm Hàn Quốc chính hãng, serumcapam, serumhyaluronic, cicabalancing, gcnature, serumhanquoc, serumcapnuoc, duongamchuyensau, serumdacangbong, myphamhan, seruminiacinamide, serumphucholi, skincarehanquoc, serumchodakho, hyaluronicacid, tinhchatha, serumcangbong, serumocsen, gcnatureserum, serumphuchoida, tinhchatcapam, tinhchatduongam, dacangmong, myphamhanquocchinhhang"}', 'https://s.shopee.vn/3LOp3cBoBe', 'https://vt.tiktok.com/ZS965T7PXBPV6-Y08Dv/', 1, 3, 1, '2026-07-03 17:27:54', '2026-07-27 11:57:36', 'Serum Cấp Ẩm Chuyên Sâu SKIN BALANCING HYALURONIC GC NATURE Cấp Nước Đa Tầng Căng Bóng Da Hàn Quốc\n🌿 Làm sáng đều màu, mờ vết thâm sạm nhờ Niacinamide\n🌿 Cấp nước đa tầng, da căng bóng tức thì nhờ 8 dạng Hyaluronic Acid\n🌿 Làm dịu da nh