INSERT INTO `products` (`id`, `product_id`, `sku`, `name`, `short_name`, `category_id`, `category_name`, `price`, `original_price`, `discount`, `badge`, `rating`, `sold`, `stock`, `brand`, `description`, `seo_tags`, `shopee_url`, `tiktok_url`, `is_flash_sale`, `flash_sale_percent`, `is_active`, `created_at`, `updated_at`, `features_vn`, `features_en`, `footer_info`, `production_year`, `clearance_price`, `daily_sale_price`, `campaign_price`, `off_platform_price`, `warranty_data`, `youtube_url`, `origin`, `volume`, `ingredients`) VALUES (28, 'serum-duong-trang-da-vitamin-c', 'TCDT', 'Serum Dưỡng Trắng DA VITAMIN-C GC NATURE  Mờ Thâm Nám Chống Oxy Hóa Hồi Phục Da Hàn Quốc', NULL, NULL, 'Serum / Tinh chất đặc trị', 360000, 400000, 10, 'BestSeller', '5', 25, 99, 'GC Nature', 'Serum Dưỡng Trắng Da VITAMIN-C GC NATURE Mờ Thâm Nám Chống Oxy Hoá Hồi Phục Da\n✨ Vì sao bạn sẽ thích?\nDa xỉn màu, nhiều đốm thâm sau mụn, tone da không đều và thiếu sức sống? Serum VITAMIN-C GC NATURE chính là ""ly nước cam ép"" cho làn da mệt mỏi, với bộ ba dưỡng chất Vitamin C – Vitamin E – Sea Buckthorn giúp da sáng dần đều màu, mờ thâm và lấy lại vẻ rạng rỡ tự nhiên. Kết cấu serum mỏng nhẹ, thấm nhanh, không gây bí da, phù hợp dùng cả sáng lẫn tối để cảm nhận làn da tươi tắn, mịn màng theo từng ngày.\n\n✨ ƯU ĐIỂM NỔI BẬT\n- Da sáng đều màu một cách an toàn nhờ Sodium Ascorbyl Phosphate (SAP) — dẫn xuất Vitamin C bền vững, dịu nhẹ\n- Chống oxy hoá và mờ thâm sạm nhờ Tocopherol (Vitamin E) — bộ đôi ""song kiếm hợp bích"" cùng Vitamin C \n- Làm dịu da đỏ và phục hồi da khoẻ : Hippophae Rhamnoides (tinh dầu tắc biển) — giàu vitamin tự nhiên\n- Làm sáng, kiềm dầu, dưỡng ẩm và nuôi dưỡng da mềm mịn từ Niacinamide & Panthenol\n- Cấp ẩm tức thì, giữ da căng mọng suốt ngày dài  từ Hyaluronic Acid\n- Kết cấu lỏng nhẹ, thấm nhanh, không bết dính — phù hợp mọi loại da, kể cả da dầu mụn\n\n✨ THÔNG TIN THƯƠNG HIỆU\nGC Nature (GC 네이처) là thương hiệu mỹ phẩm đến từ Hàn Quốc, nổi tiếng với các dòng sản phẩm chăm sóc da chuyên sâu và công nghệ Hàn Quốc hiện đại. Các dòng sản phẩm đã bán chạy TOP đầu tại Hàn Quốc, trên Coupang, Olive Young, TOP tìm kiếm trên Naver, được cộng đồng nghệ sỹ Hàn Quốc dùng và feedback uy tín. Sản phẩm được sản xuất bởi CELLCOCO.CO.,LTD, được nhập khẩu và phân phối chính hãng độc quyền bởi GC Nature tại Việt Nam.\n\n✨ THÀNH PHẦN CHÍNH\nWater, Glycerin, Dipropylene Glycol, Niacinamide, Sodium Ascorbyl Phosphate (SAP – dẫn xuất Vitamin C), Betaine, 1,2-Hexanediol, Tocopherol (Vitamin E), Hippophae Rhamnoides Fruit Extract (Sea Buckthorn), Panthenol, Allantoin, Adenosine, Sodium Hyaluronate, Hydrolyzed Hyaluronic Acid, Beta-Glucan, Caprylyl Glycol, Xanthan Gum, Hydroxyethylcellulose, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Triethanolamine, Disodium EDTA, Chlorphenesin, Butylene Glycol, Pentylene Glycol, Fragrance.\n\n✨ HƯỚNG DẪN SỬ DỤNG\nMột nghi thức nhỏ cho làn da rạng rỡ mỗi sáng và tối: \nBước 1: Làm sạch nhẹ nhàng để da như tờ giấy trắng chờ nét bút \nBước 2: Lấy 3–4 giọt serum thoa khi da còn hơi ẩm, xoa đều rồi vỗ nhẹ để đánh thức làn da \nBước 3: Đợi khoảng 1 phút cho serum thấm trọn vẹn \nBước 4: Khoá ẩm bằng kem dưỡng để ""niêm phong"" dưỡng chất \nBước 5: Ban ngày nhớ thoa kem chống nắng – Vitamin C thích ánh sáng, nhưng da thì không\n\n💡 Lưu ý nhỏ: – Da nhạy cảm nên dùng cách ngày, 3–4 lần/tuần rồi tăng dần – Tránh thoa lên vùng da có vết thương hở – Đang dùng AHA/BHA/Retinol thì tách buổi hoặc dùng xen kẽ để da không bị ""quá tải""\n\n✨ HƯỚNG DẪN BẢO QUẢN\n– Để nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp và nhiệt độ cao\n – Đậy kín nắp ngay sau khi sử dụng để giữ Vitamin C không bị oxy hoá\n – Để xa tầm tay trẻ em \n– Ngưng dùng và rửa sạch với nước nếu xuất hiện dấu hiệu khó chịu\n\n\n#serumvitaminc #gcnature #serummothamnam #serumduongtrang #serumchongoxyhoa #serumhanquoc #vitamincserum #seabuckthorn #serumphucholi #myphamhan #serumsangda #skincarehanquoc #seruminiacinamide #serumdaumun #serumdeumauda', '{"title":"Serum Dưỡng Trắng DA VITAMIN-C GC NATURE  Mờ Thâm Nám Chống Oxy Hóa Hồi Phục Da Hàn Quốc","desc":"Serum Dưỡng Trắng DA VITAMIN-C GC NATURE  Mờ Thâm Nám Chống Oxy Hóa Hồi Phục Da Hàn Quốc\\n- Da sáng đều màu một cách an toàn nhờ Sodium Ascorbyl Phosphate (SAP) — dẫn xuất Vitamin C bền vững, dịu nhẹ\\n- Chống oxy hoá và mờ thâm sạm nhờ Tocopherol (Vitamin E) — bộ đôi \\"\\"song kiếm hợp bích\\"\\" cùng Vitamin C \\n- Làm dịu da đỏ và phục hồi da khoẻ : Hippophae Rhamnoides (tinh dầu tắc biển) — giàu vitamin tự nhiên\\n- Làm sáng, kiềm dầu, dưỡng ẩm và nuôi dưỡng da mềm mịn từ Niacinamide & Panthenol\\n- Cấp ẩm tức thì, giữ da căng mọng suốt ngày dài  từ Hyaluronic Acid\\n- Kết cấu lỏng nhẹ, thấm nhanh, không bết dính — phù hợp mọi loại da, kể cả da dầu mụn","keywords":"serum vitamin C, tinh chất vitamin C, serum trắng da, dưỡng trắng da, mờ thâm nám, chống oxy hóa, mờ thâm mụn, serum mờ thâm, serum GC Nature, mỹ phẩm Hàn, phục hồi da, serum sáng da, vitamin C SAP, serum vitamin E, cấp ẩm da, làm dịu da, serum dưỡng trắng da mặt, serum vitamin C Hàn Quốc, tinh chất dưỡng trắng GC Nature, serum mờ thâm nám hiệu quả, serum chống oxy hóa da, tinh chất mờ thâm sau mụn, serum vitamin C cho da mụn, serum sáng da đều màu, serum phục hồi da rạng rỡ, mỹ phẩm Hàn Quốc chính hãng, tinh chất vitamin C SAP, serum mờ thâm sáng da, serumvitaminc, gcnature, serummothamnam, serumduongtrang, serumchongoxyhoa, serumhanquoc, vitamincserum, seabuckthorn, serumphucholi, myphamhan, serumsangda, skincarehanquoc, seruminiacinamide, serumdaumun, serumdeumauda, tinhchatsangda, serumvitamincGCnature, serummoithamnam, serumtrangdaHanquoc"}', 'https://s.shopee.vn/3g1fUbPCLo', 'https://vt.tiktok.com/ZS965w2aKVj2N-DJyVX/', 1, 4, 1, '2026-07-03 17:33:07', '2026-07-27 12:03:07', 'Serum Dưỡng Trắng DA VITAMIN-C GC NATURE  Mờ Thâm Nám Chống Oxy Hóa Hồi Phục Da Hàn Quốc\n- Da sáng đều màu một cách an toàn nhờ Sodium Ascorbyl Phosphate (SAP) — dẫn xuất Vitamin C bền vững, dịu nhẹ\n- Chống oxy hoá và mờ thâm sạm nhờ Tocopherol (Vitamin E) — bộ đôi ""song kiếm hợp bích"" cùng Vitamin C \n- Làm dịu da đỏ và phục hồi da khoẻ : Hippophae Rhamnoides (tinh dầu tắc biển) — giàu vitamin tự nhiên\n- Làm sáng, kiềm dầu, dưỡng ẩm và nuôi dưỡng da mềm mịn từ Niacinamide & Panthenol\n- Cấp ẩm tức thì, giữ da căng mọng suốt ngày dài  từ Hyaluronic Acid\n- Kết cấu lỏng nhẹ, thấm nhanh, không bết dính — phù hợp mọi loại da, kể cả da dầu mụn', 'Niacinamide, Panthenol, Adenosine, Sodium Hyaluronate, Ascorbic Acid, Beta-Glucan, Lactobacillus/Soybean Ferment Extract, Sodium Ascorbyl Phosphate, Tocopherol, Hippophae Rhamnoides Extract.', NULL, 2026, 0, 360000, 0, 0, '', NULL, 'Hàn Quốc', '50ml', 'Water, Glycerin, Dipropylene Glycol, Glycereth-26, Niacinamide, Betaine, 1,2-Hexanediol, PEG-60 Hydrogenated Castor Oil, Chlorphenesin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Triethanolamine, Caprylyl Glycol, Panthenol, Xanthan Gum, Hydroxyethylcellulose, Allantoin, Adenosine, Disodium EDTA, Sodium Polyacrylate, Fragrance (Perfume/Parfum), Butylene Glycol, Sodium Hyaluronate, Ascorbic Acid, Beta-Glucan, Hydrogenated Lecithin, Polyglyceryl-10 Stearate, CI 19140, Salix Alba (Willow) Bark Extract, Lactobacillus/Soybean Ferment Extract, Hippophae Rhamnoides Extract, Cinnamomum Cassia Bark Extract, CI 15985, Aloe Vera Vesicles, Sodium Ascorbyl Phosphate, Scutellaria Baicalensis Root Extract, Portulaca Oleracea Extract, Origanum Vulgare Leaf Extract, Chamaecyparis Obtusa Leaf Extract, Pyridoxine, Biotin, Tocopherol, Cyanocobalamin, Thiamine HCl, Riboflavin, Beta-Carotene.');
INSERT INTO `products` (`id`, `product_id`, `sku`, `name`, `short_name`, `category_id`, `category_name`, `price`, `original_price`, `discount`, `badge`, `rating`, `sold`, `stock`, `brand`, `description`, `seo_tags`, `shopee_url`, `tiktok_url`, `is_flash_sale`, `flash_sale_percent`, `is_active`, `created_at`, `updated_at`, `features_vn`, `features_en`, `footer_info`, `production_year`, `clearance_price`, `daily_sale_price`, `campaign_price`, `off_platform_price`, `warranty_data`, `youtube_url`, `origin`, `volume`, `ingredients`) VALUES (29, 'kem-duong-nang-tone-moisture-tone-up-cream', 'KDNTTU', 'Kem Dưỡng Nâng Tone MOISTURE TONE UP CREAM GC NATURE Bật Tông Tự Nhiên Thay Thế Kem Lót Hàn Quốc', NULL, NULL, 'Kem dưỡng / Gel dưỡng ẩm', 351000, 390000, 10, 'BestSeller', '5', 62, 992, 'GC Nature', 'Kem Dưỡng Nâng Tone GC NATURE MOISTURE TONE UP CREAM Bật Tông Tự Nhiên Thay Thế Kem Lót\n✨ Vì sao bạn sẽ thích?\nVừa dưỡng ẩm sâu, vừa nâng tone tức thì cho làn da sáng mịn tự nhiên như vừa ngủ đủ giấc. Chất kem mỏng nhẹ, thấm nhanh, không bết dính, có thể dùng thay kem lót để lớp trang điểm bám lâu và mượt hơn. Phù hợp cho nàng bận rộn, muốn ra đường nhanh mà vẫn rạng rỡ.\n\n✨ ƯU ĐIỂM NỔI BẬT\n-  Nâng tông tự nhiên, không trắng bệch, không lộ mảng \n-  Cấp ẩm chuyên sâu nhờ Hyaluronic Acid, Glycerin, DNA cá hồi \n-  Làm sáng và đều màu da với Niacinamide, Glutathione, Vitamin C \n-  Hỗ trợ chống nắng nhẹ với Titanium Dioxide, Zinc Oxide \n-  Làm dịu da nhạy cảm nhờ chiết xuất rau má (Centella Asiatica), cam thảo, hoa cúc \n-  Chống oxy hóa với Vitamin E, Adenosine giúp da căng mịn \n-  Kết cấu mỏng nhẹ, thay thế hoàn hảo cho kem lót \n-  Hương thơm dịu, dễ chịu\n\n✨ THÔNG TIN THƯƠNG HIỆU\nGC Nature (GC 네이처) là thương hiệu mỹ phẩm đến từ Hàn Quốc, nổi tiếng với các dòng sản phẩm chăm sóc da chuyên sâu và công nghệ Hàn Quốc hiện đại. Các dòng sản phẩm đã bán chạy TOP đầu tại Hàn Quốc, trên Coupang, Olive Young, TOP tìm kiếm trên Naver, được cộng đồng nghệ sỹ Hàn Quốc dùng và feedback uy tín. Sản phẩm được sản xuất bởi CELLCOCO.CO.,LTD, được nhập khẩu và phân phối chính hãng độc quyền bởi GC Nature tại Việt Nam.\n\n✨ THÀNH PHẦN CHÍNH\n• DNA cá hồi (Salmon DNA): phục hồi, cấp ẩm sâu, làm da căng bóng \n• Niacinamide & Glutathione: làm sáng, mờ thâm, đều màu da \n• Sodium Hyaluronate: giữ ẩm, da mềm mịn cả ngày \n• Titanium Dioxide & Zinc Oxide: nâng tông, chống nắng vật lý \n• Centella Asiatica (rau má): làm dịu, giảm kích ứng \n• Chiết xuất lựu, dâu tằm, bạch quả, cam thảo, trà xanh: chống oxy hóa, dưỡng da khỏe \n• Vitamin C (Ascorbic Acid) & Vitamin E (Tocopherol): sáng da, chống lão hóa \n• Adenosine: giảm dấu hiệu lão hóa, da săn chắc \n• Cyclopentasiloxane, Beeswax: tạo lớp màng mịn, nâng tông tự nhiên\n\n✨ HƯỚNG DẪN SỬ DỤNG\nBước 1: Làm sạch da, dùng toner cân bằng độ ẩm \nBước 2: Lấy lượng vừa đủ (cỡ hạt đậu) \nBước 3: Chấm 5 điểm lên trán, mũi, cằm, hai má \nBước 4: Tán đều theo chiều từ trong ra ngoài, vỗ nhẹ để kem thấm \nBước 5: Có thể dùng thay kem lót trước khi đánh nền\n\n👉 Dùng được sáng và tối, kết hợp kem chống nắng khi ra ngoài.\n\n✨ HƯỚNG DẪN BẢO QUẢN\n• Đậy kín nắp sau khi sử dụng \n• Bảo quản nơi khô thoáng, tránh ánh nắng trực tiếp \n• Nhiệt độ lý tưởng: dưới 30°C \n• Tránh để gần nguồn nhiệt hoặc nơi ẩm ướt \n• Dùng tốt nhất trong 12 tháng sau khi mở nắp\n\n#kemnangtone #GCNature #toneupcream #kemduongam #kemlothanquoc #mỹphẩmhàn #kemDNAcahoi #kemduongtrang #skincarehanquoc #kemduongmat #toneupkorea #kembattong #kemduongtrangda #mypham_han #kemduongdadam', '{"title":"Kem Dưỡng Nâng Tone MOISTURE TONE UP CREAM GC NATURE Bật Tông Tự Nhiên Thay Thế Kem Lót Hàn Quốc","desc":"Kem Dưỡng Nâng Tone MOISTURE TONE UP CREAM GC NATURE Bật Tông Tự Nhiên Thay Thế Kem Lót Hàn Quốc\\n-  Nâng tông tự nhiên, không trắng bệch, không lộ mảng \\n-  Cấp ẩm chuyên sâu nhờ Hyaluronic Acid, Glycerin, DNA cá hồi \\n-  Làm sáng và đều màu da với Niacinamide, Glutathione, Vitamin C \\n-  Hỗ trợ chống nắng nhẹ với Titanium Dioxide, Zinc Oxide \\n-  Làm dịu da nhạy cảm nhờ chiết xuất rau má (Centella Asiatica), cam thảo, hoa cúc \\n-  Chống oxy hóa với Vitamin E, Adenosine giúp da căng mịn \\n-  Kết cấu mỏng nhẹ, thay thế hoàn hảo cho kem lót \\n-  Hương thơm dịu, dễ chịu","keywords":"kem nâng tone, kem dưỡng ẩm, kem dưỡng trắng, kem lót, mỹ phẩm Hàn, kem bật tông, kem dưỡng da, sáng đều màu, da căng bóng, kem GC nature, kem dưỡng nâng tone tự nhiên, kem dưỡng ẩm nâng tone da, kem nâng tone GC nature, kem lót trang điểm Hàn Quốc, kem dưỡng trắng da mặt, kem DNA cá hồi nâng tone, kem bật tông thay kem lót, kem dưỡng sáng đều màu, kem dưỡng da căng bóng, kemnangtone, gcnature, toneupcream, kemduongam, kemlothanquoc, mỹphẩmhàn, kemdnacahoi, kemduongtrang, skincarehanquoc, kemduongmat, toneupkorea, kembattong, kemduongtrangda, mypham_han, kemduongdadam"}', 'https://s.shopee.vn/6Aj0UM08kC', 'https://vt.tiktok.com/ZS965wJBTjNSV-W6mLu/', 1, 5, 1, '2026-07-03 17:37:55', '2026-07-27 11:56:56', 'Kem Dưỡng Nâng Tone MOISTURE TONE UP CREAM GC NATURE Bật Tông Tự Nhiên Thay Thế Kem Lót Hàn Quốc\n-  Nâng tông tự nhiên, không trắng bệch, không lộ mảng \n-  Cấp ẩm chuyên sâu nhờ Hyaluronic Acid, Glycerin, DNA cá hồi \n-  Làm sáng và đều màu da với Niacinamide, Glutathione, Vitamin C \n-  Hỗ trợ chống nắng nhẹ với Titanium Dioxide, Zinc Oxide \n-  Làm dịu da nhạy cảm nhờ chiết xuất rau má (Centella Asiatica), cam thảo, hoa cúc \n-  Chống oxy hóa với Vitamin E, Adenosine giúp da căng mịn \n-  Kết cấu mỏng nhẹ, thay thế hoàn hảo cho kem lót \n-  Hương thơm dịu, dễ chịu', 'Niacinamide, DNA, Centella Asiatica Extract, Sodium Hyaluronate, Glutathione, Ascorbic Acid, Adenosine, Lactobacillus/Soybean Ferment Extract, Tocopherol, Glycyrrhiza Glabra (Licorice) Root Extract.', NULL, 2026, 0, 351000, 0, 0, '', NULL, 'Hàn Quốc', '50ml', 'Water, Cyclopentasiloxane, Cyclohexasiloxane, Butylene Glycol, Titanium Dioxide, Mineral Oil, Glycerin, Cetyl PEG/PPG-10/1 Dimethicone, Beeswax, DNA, Centella Asiatica Extract, Scutellaria Baicalensis Root Extract, Punica Granatum Fruit Extract, Morus Alba Fruit Extract, Ginkgo Biloba Nut Extract, Ficus Carica (Fig) Fruit Extract, Polygonum Cuspidatum Root Extract, Salix Alba (Willow) Bark Extract, Lactobacillus/Soybean Ferment Extract, Glycyrrhiza Glabra (Licorice) Root Extract, Cinnamomum Cassia Bark Extract, Camellia Sinensis Leaf Extract, Sodium Acrylate/Sodium Acryloyldimethyl Taurate Copolymer, 1,2-Hexanediol, Sorbitan Sesquioleate, Isohexadecane, Caprylyl Glycol, Polysorbate 80, Aluminum Hydroxide, Disodium EDTA, Triethoxycaprylylsilane, Sodium Hyaluronate, Niacinamide, Zinc Oxide, Glutathione, Ethylhexyl Methoxycinnamate, CI 16185 (Amaranth), Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Ascorbic Acid, Adenosine, Isoamyl p-Methoxycinnamate, Terephthalylidene Dicamphor Sulfonic Acid, Rosmarinus Officinalis (Rosemary) Leaf Extract, Portulaca Oleracea Extract, Origanum Vulgare Leaf Extract, Chamomilla Recutita (Matricaria) Flower Extract, Chamaecyparis Obtusa Leaf Extract, Tocopherol, Fragrance.');
INSERT INTO `products` (`id`, `product_id`, `sku`, `name`, `short_name`, `category_id`, `category_name`, `price`, `original_price`, `discount`, `badge`, `rating`, `sold`, `stock`, `brand`, `description`, `seo_tags`, `shopee_url`, `tiktok_url`, `is_flash_sale`, `flash_sale_percent`, `is_active`, `created_at`, `updated_at`, `features_vn`, `features_en`, `footer_info`, `production_year`, `clearance_price`, `daily_sale_price`, `campaign_price`, `off_platform_price`, `warranty_data`, `youtube_url`, `origin`, `volume`, `ingredients`) VALUES (30, 'mat-na-tinh-chat-phuc-hoi-lam-diu-da-chuyen-sau', 'MMC', 'Mặt Nạ Tinh Chất Phục Hồi & Làm Dịu Da Chuyên Sâu SKIN BALANCING CICA COMPLEX SERUM MASK GC NATURE Hàn Quốc', NULL, NULL, 'Mặt nạ (Giấy/Đất sét/Ngủ)', 240000, 400000, 40, 'BestSeller', '5', 215, 99, 'GC Nature', 'Mặt Nạ Tinh Chất Phục Hồi & Làm Dịu Da Chuyên Sâu GC NATURE SKIN BALANCING CICA COMPLEX SERUM MASK\n✨ Vì sao bạn sẽ thích?\nLàn da đang khô căng, mẩn đỏ, mệt mỏi sau một ngày dài tiếp xúc nắng, bụi và máy lạnh? GC NATURE Cica Complex Serum Mask chính là ""miếng dán cứu nguy"" bạn cần. Mỗi miếng mặt nạ thấm đẫm 23g tinh chất Cica giàu dưỡng chất, ôm sát từng đường nét gương mặt, mang lại cảm giác mát dịu tức thì và làn da căng mọng, mềm mại chỉ sau 15 phút thư giãn.\n\n✨ ƯU ĐIỂM NỔI BẬT\n- Làm sáng đều màu da, mờ thâm sạm, se khít lỗ chân lông nhờ Niacinamide 2% hỗ trợ \n- Làm dịu da nhạy cảm, đỏ rát hiệu quả bằng bộ tứ Cica chuẩn Hàn (Asiaticoside, Madecassoside, Madecassic Acid, Asiatic Acid)\n- Cấp ẩm sâu, khóa ẩm bền lâu nhờ Glycerin 12%, Sodium Hyaluronate và Beta-Glucan. \n- Nuôi dưỡng da khỏe từ bên trong từ bộ 10+ chiết xuất thực vật (Lotus, Aloe Vera, Pumpkin, Pomegranate, Mume...).\n- Giúp da đàn hồi, phục hồi hàng rào bảo vệ tự nhiên nhờ  Adenosine & Panthenol \n- Kết cấu serum lỏng nhẹ, thẩm thấu nhanh, không bết dính. \n✅ Không cần rửa lại với nước – tiện dụng mọi lúc.\n\n✨ THÔNG TIN THƯƠNG HIỆU\nGC Nature (GC 네이처) là thương hiệu mỹ phẩm đến từ Hàn Quốc, nổi tiếng với các dòng sản phẩm chăm sóc da chuyên sâu và công nghệ Hàn Quốc hiện đại. Các dòng sản phẩm đã bán chạy TOP đầu tại Hàn Quốc, trên Coupang, Olive Young, TOP tìm kiếm trên Naver, được cộng đồng nghệ sỹ Hàn Quốc dùng và feedback uy tín. Sản phẩm được sản xuất bởi CELLCOCO.CO.,LTD, được nhập khẩu và phân phối chính hãng độc quyền bởi GC Nature tại Việt Nam.\n\n✨ THÀNH PHẦN CHÍNH\n- Cica Complex (Centella Asiatica + Asiaticoside + Madecassoside + Madecassic Acid + Asiatic Acid): làm dịu, giảm kích ứng, củng cố da yếu. \n- Niacinamide 2%: dưỡng sáng, đều màu da, kiểm soát dầu. \n- Sodium Hyaluronate + Beta-Glucan + Glycerin: cấp – giữ ẩm đa tầng. \n- Panthenol (B5) + Allantoin: dịu da, làm mềm và phục hồi. \n- Adenosine: nâng đỡ độ săn chắc, giảm dấu hiệu lão hóa. \n- Tinh chất hoa & thảo mộc: Hoa Sen, Lựu, Mơ, Bí Đỏ, Lô Hội, Tảo Bẹ Nhật, Xương Rồng, Propolis... nuôi dưỡng da rạng rỡ.\n\n✨ HƯỚNG DẪN SỬ DỤNG\nLàm sạch da và cân bằng bằng toner.\nMở gói, đắp mặt nạ lên mặt, vuốt nhẹ cho ôm sát da.\nThư giãn 15–20 phút, gỡ mặt nạ ra.\nVỗ nhẹ lượng tinh chất còn lại để da hấp thu hoàn toàn. \n👉 Không cần rửa lại với nước. Dùng 2–3 lần/tuần để có hiệu quả tốt nhất.\n\n✨ HƯỚNG DẪN BẢO QUẢN\nBảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp và nhiệt độ cao. Dùng ngay sau khi mở gói. Bảo quản trong ngăn mát tủ lạnh để có cảm giác mát dịu hơn khi sử dụng.\n\n#GCNature #CicaMask #MatNaCica #MatNaHan #MatNaPhucHoi #MatNaDuongAm #MatNaLamDiu #SkinBalancing #MyPhamHan #ChamSocDa #DaNhayCam #DaKho #Niacinamide #CentellaAsiatica #MatNaGiay', '{"title":"Mặt Nạ Tinh Chất Phục Hồi & Làm Dịu Da Chuyên Sâu SKIN BALANCING CICA COMPLEX SERUM MASK GC NATURE Hàn Quốc","desc":"Mặt Nạ Tinh Chất Phục Hồi & Làm Dịu Da Chuyên Sâu SKIN BALANCING CICA COMPLEX SERUM MASK GC NATURE Hàn Quốc\\n- Làm sáng đều màu da, mờ thâm sạm, se khít lỗ chân lông nhờ Niacinamide 2% hỗ trợ \\n- Làm dịu da nhạy cảm, đỏ rát hiệu quả bằng bộ tứ Cica chuẩn Hàn (Asiaticoside, Madecassoside, Madecassic Acid, Asiatic Acid)\\n- Cấp ẩm sâu, khóa ẩm bền lâu nhờ Glycerin 12%, Sodium Hyaluronate và Beta-Glucan. \\n- Nuôi dưỡng da khỏe từ bên trong từ bộ 10+ chiết xuất thực vật (Lotus, Aloe Vera, Pumpkin, Pomegranate, Mume...).\\n- Giúp da đàn hồi, phục hồi hàng rào bảo vệ tự nhiên nhờ  Adenosine & Panthenol \\n- Kết cấu serum lỏng nhẹ, thẩm thấu nhanh, không bết dính. \\n- Không cần rửa lại với nước – tiện dụng mọi lúc.","keywords":"mặt nạ cica, mặt nạ giấy, mặt nạ Hàn, mask phục hồi, làm dịu da, dưỡng ẩm sâu, mặt nạ B5, phục hồi da, mask giấy, da nhạy cảm, cấp ẩm sâu, tinh chất cica, mặt nạ GC nature, da khô, giảm mẩn đỏ, mặt nạ cấp ẩm, mỹ phẩm Hàn, chăm sóc da, mặt nạ cica phục hồi da, mặt nạ giấy Hàn Quốc, mặt nạ làm dịu da nhạy cảm, mặt nạ dưỡng ẩm sâu, mặt nạ phục hồi cica, mặt nạ tinh chất rau má, cica mask GC nature, mặt nạ phục hồi da yếu, mặt nạ cấp ẩm đa tầng, mặt nạ giảm đỏ rát, mặt nạ giấy dưỡng sáng da, gcnature, cicamask, matnacica, matnahan, matnaphuchoi, matnaduongam, matnalamdiu, skinbalancing, myphamhan, chamsocda, danhaycam, dakho, niacinamide, centellaasiatica, matnagiay"}', 'https://s.shopee.vn/4Axw6ioSg0', 'https://vt.tiktok.com/ZS965wkdNPMrW-ko6DG/', 1, 6, 1, '2026-07-03 17:47:53', '2026-07-27 12:00:29', 'Mặt Nạ Tinh Chất Phục Hồi & Làm Dịu Da Chuyên Sâu SKIN BALANCING CICA COMPLEX SERUM MASK GC NATURE Hàn Quốc\n- Làm sáng đều màu da, mờ thâm sạm, se khít lỗ chân lông nhờ Niacinamide 2% hỗ trợ \n- Làm dịu da nhạy cảm, đỏ rát hiệu quả bằng bộ tứ Cica chuẩn Hàn (Asiaticoside, Madecassoside, Madecassic Acid, Asiatic Acid)\n- Cấp ẩm sâu, khóa ẩm bền lâu nhờ Glycerin 12%, Sodium Hyaluronate và Beta-Glucan. \n- Nuôi dưỡng da khỏe từ bên trong từ bộ 10+ chiết xuất thực vật (Lotus, Aloe Vera, Pumpkin, Pomegranate, Mume...).\n- Giúp da đàn hồi, phục hồi hàng rào bảo vệ tự nhiên nhờ  Adenosine & Panthenol \n- Kết cấu serum lỏng nhẹ, thẩm thấu nhanh, không bết dính. \n- Không cần rửa lại với nước – tiện dụng mọi lúc.', 'Niacinamide, Panthenol, Adenosine, Sodium Hyaluronate, Beta-Glucan, Centella Asiatica Extract, Lactobacillus Ferment, Propolis Extract, Madecassoside, Asiaticoside.', NULL, 2026, 0, 240000, 0, 0, '', NULL, 'Hàn Quốc', '23ml', 'Water, Glycerin, Dipropylene Glycol, Glycereth-26, Niacinamide, Betaine, 1,2-Hexanediol, PEG-60 Hydrogenated Castor Oil, Chlorphenesin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Triethanolamine, Caprylyl Glycol, Panthenol, Xanthan Gum, Hydroxyethylcellulose, Allantoin, Adenosine, Disodium EDTA, Sodium Polyacrylate, Fragrance (Perfume/Parfum), Butylene Glycol, Sodium Hyaluronate, Viola Mandshurica Flower Extract, Ulmus Davidiana Root Extract, Laminaria Japonica Extract, Dioscorea Japonica Root Extract, Aloe Barbadensis Leaf Extract, Beta-Glucan, Centella Asiatica Extract, CI 19140, Punica Granatum Flower Extract, Prunus Mume Root Extract, Prunus Mume Flower Extract, Portulaca Oleracea Extract, Opuntia Ficus-Indica Stem Extract, Nelumbo Nucifera Flower Extract, Cucurbita Pepo (Pumpkin) Fruit Extract, Althaea Rosea Root Extract, Althaea Rosea Flower Extract, Nelumbo Nucifera Root Extract, Lactobacillus Ferment, CI 42090, Propolis Extract, Asiaticoside, Madecassoside, Madecassic Acid, Asiatic Acid.');
INSERT INTO `products` (`id`, `product_id`, `sku`, `name`, `short_name`, `category_id`, `category_name`, `price`, `original_price`, `discount`, `badge`, `rating`, `sold`, `stock`, `brand`, `description`, `seo_tags`, `shopee_url`, `tiktok_url`, `is_flash_sale`, `flash_sale_percent`, `is_active`, `created_at`, `updated_at`, `features_vn`, `features_en`, `footer_info`, `production_year`, `clearance_price`, `daily_sale_price`, `campaign_price`, `off_platform_price`, `warranty_data`, `youtube_url`, `origin`, `volume`, `ingredients`) VALUES (31, 'mat-na-cap-am-chuyen-sau-serum-mask-hyaluronic', 'MMH', 'Mặt nạ Cấp Ẩm Chuyên Sâu SKIN BALANCING HYALURONIC SERUM MASK GC NATURE Hàn Quốc', NULL, NULL, 'Mặt nạ (Giấy/Đất sét/Ngủ)', 240000, 400000, 40, 'BestSeller', '5', 97, 99, 'GC Nature', 'Mặt Nạ Tinh Chất Phục Hồi & Làm Dịu Da Chuyên Sâu GC NATURE SKIN BALANCING HYALURONIC SERUM MASK\n✨ Vì sao bạn sẽ thích?\nLàn da đang khô căng, mẩn đỏ, mệt mỏi sau một ngày dài tiếp xúc nắng, bụi và máy lạnh? GC NATURE HYALURONIC Serum Mask chính là ""miếng dán cứu nguy"" bạn cần. Mỗi miếng mặt nạ thấm đẫm 23g tinh chất Cica giàu dưỡng chất, ôm sát từng đường nét gương mặt, mang lại cảm giác mát dịu tức thì và làn da căng mọng, mềm mại chỉ sau 15 phút thư giãn.\n\n✨ ƯU ĐIỂM NỔI BẬT\n- Làm sáng đều màu da, mờ thâm sạm, se khít lỗ chân lông nhờ Niacinamide 2% hỗ trợ \n- Làm dịu da nhạy cảm, đỏ rát hiệu quả bằng bộ tứ Cica chuẩn Hàn (Asiaticoside, Madecassoside, Madecassic Acid, Asiatic Acid)\n- Cấp ẩm sâu, khóa ẩm bền lâu nhờ Glycerin 12%, Sodium Hyaluronate và Beta-Glucan. \n- Nuôi dưỡng da khỏe từ bên trong từ bộ 10+ chiết xuất thực vật (Lotus, Aloe Vera, Pumpkin, Pomegranate, Mume...).\n- Giúp da đàn hồi, phục hồi hàng rào bảo vệ tự nhiên nhờ  Adenosine & Panthenol \n- Kết cấu serum lỏng nhẹ, thẩm thấu nhanh, không bết dính. \n✅ Không cần rửa lại với nước – tiện dụng mọi lúc.\n\n✨ THÔNG TIN THƯƠNG HIỆU\nGC Nature (GC 네이처) là thương hiệu mỹ phẩm đến từ Hàn Quốc, nổi tiếng với các dòng sản phẩm chăm sóc da chuyên sâu và công nghệ Hàn Quốc hiện đại. Các dòng sản phẩm đã bán chạy TOP đầu tại Hàn Quốc, trên Coupang, Olive Young, TOP tìm kiếm trên Naver, được cộng đồng nghệ sỹ Hàn Quốc dùng và feedback uy tín. Sản phẩm được sản xuất bởi CELLCOCO.CO.,LTD, được nhập khẩu và phân phối chính hãng độc quyền bởi GC Nature tại Việt Nam.\n\n✨ THÀNH PHẦN CHÍNH\n- Cica Complex (Centella Asiatica + Asiaticoside + Madecassoside + Madecassic Acid + Asiatic Acid): làm dịu, giảm kích ứng, củng cố da yếu. \n- Niacinamide 2%: dưỡng sáng, đều màu da, kiểm soát dầu. \n- Sodium Hyaluronate + Beta-Glucan + Glycerin: cấp – giữ ẩm đa tầng. \n- Panthenol (B5) + Allantoin: dịu da, làm mềm và phục hồi. \n- Adenosine: nâng đỡ độ săn chắc, giảm dấu hiệu lão hóa. \n- Tinh chất hoa & thảo mộc: Hoa Sen, Lựu, Mơ, Bí Đỏ, Lô Hội, Tảo Bẹ Nhật, Xương Rồng, Propolis... nuôi dưỡng da rạng rỡ.\n\n✨ HƯỚNG DẪN SỬ DỤNG\nLàm sạch da và cân bằng bằng toner.\nMở gói, đắp mặt nạ lên mặt, vuốt nhẹ cho ôm sát da.\nThư giãn 15–20 phút, gỡ mặt nạ ra.\nVỗ nhẹ lượng tinh chất còn lại để da hấp thu hoàn toàn. \n👉 Không cần rửa lại với nước. Dùng 2–3 lần/tuần để có hiệu quả tốt nhất.\n\n✨ HƯỚNG DẪN BẢO QUẢN\nBảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp và nhiệt độ cao. Dùng ngay sau khi mở gói. Bảo quản trong ngăn mát tủ lạnh để có cảm giác mát dịu hơn khi sử dụng.\n\n#GCNature #CicaMask #MatNaCica #MatNaHan #MatNaPhucHoi #MatNaDuongAm #MatNaLamDiu #SkinBalancing #MyPhamHan #ChamSocDa #DaNhayCam #DaKho #Niacinamide #CentellaAsiatica #MatNaGiay', '{"title":"Mặt nạ Cấp Ẩm Chuyên Sâu SKIN BALANCING HYALURONIC SERUM MASK GC NATURE Hàn Quốc","desc":"Mặt nạ Cấp Ẩm Chuyên Sâu SKIN BALANCING HYALURONIC SERUM MASK GC NATURE Hàn Quốc\\n🌿 Cấp nước đa tầng, da căng bóng tức thì nhờ 8 dạng Hyaluronic Acid\\n🌿 Làm sáng đều màu, mờ vết thâm sạm nhờ Niacinamide\\n🌿 Làm dịu da nhạy cảm, giảm mẩn đỏ nhờ Panthenol & Allantoin\\n🌿 Phục hồi, làm mềm mượt bề mặt da nhờ tinh chất Ốc Sên Hàn Quốc Snail Filtrate\\n🌿 Tăng độ đàn hồi, ngăn ngừa lão hoá sớm nhờ Beta-Glucan & Adenosine \\n🌿 Nuôi dưỡng da từ sâu bên trong bởi 7 chiết xuất thảo dược Hàn (sắn dây, cỏ ba lá, lựu, đương quy…) \\n🌿 Kết cấu lỏng nhẹ, thấm nhanh, không nhờn rít — phù hợp mọi loại da, kể cả da dầu mụn","keywords":"mặt nạ cấp ẩm, mặt nạ HA, mask giấy HA, dưỡng ẩm sâu, cấp nước đa tầng, mặt nạ Hàn, mỹ phẩm Hàn, da căng mọng, phục hồi da, mask cấp ẩm, mặt nạ cica, làm dịu da, da nhạy cảm, da khô căng, sáng đều màu, mặt nạ giấy, mặt nạ hyaluronic GC nature, mask giấy cấp ẩm sâu, mặt nạ phục hồi da yếu, mặt nạ dưỡng ẩm Hàn Quốc, mặt nạ làm dịu da nhạy cảm, mặt nạ giấy cho da khô, mặt nạ căng bóng da mặt, mặt nạ cấp nước đa tầng, gcnature, cicamask, matnacica, matnahan, matnaphuchoi, matnaduongam, matnalamdiu, skinbalancing, myphamhan, chamsocda, danhaycam, dakho, niacinamide, centellaasiatica, matnagiay"}', 'https://s.shopee.vn/50X39U7Cnj', 'https://vt.tiktok.com/ZS965wX8LSxdN-K0FKT/', 1, 7, 1, '2026-07-03 17:53:07', '2026-07-27 12:12:35', 'Mặt nạ Cấp Ẩm Chuyên Sâu SKIN BALANCING HYALURONIC SERUM MASK GC NATURE Hàn Quốc\n🌿 Cấp nước đa tầng, da căng bóng tức thì nhờ 8 dạng Hyaluronic Acid\n🌿 Làm sáng đều màu, mờ vết thâm sạm nhờ Niacinamide\n🌿 Làm dịu da nhạy cảm, giảm mẩn đỏ nhờ Panthenol & Allantoin\n🌿 Phục hồi, làm mềm mượt bề mặt da nhờ tinh chất Ốc Sên Hàn Quốc Snail Filtrate\n🌿 Tăng độ đàn hồi, ngăn ngừa lão hoá sớm nhờ Beta-Glucan & Adenosine \n🌿 Nuôi dưỡng da từ sâu bên trong bởi 7 chiết xuất thảo dược Hàn (sắn dây, cỏ ba lá, lựu, đương quy…) \n🌿 Kết cấu lỏng nhẹ, thấm nhanh, không nhờn rít — phù hợp mọi loại da, kể cả da dầu mụn', 'Niacinamide, Panthenol, Allantoin, Adenosine, Sodium Hyaluronate, Snail Secretion Filtrate, Beta-Glucan, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Hyaluronic Acid.', NULL, 2026, 0, 240000, 0, 0, '', NULL, 'Hàn Quốc', '23ml', 'Water, Glycerin, Dipropylene Glycol, Glycereth-26, Niacinamide, Betaine, 1,2-Hexanediol, PEG-60 Hydrogenated Castor Oil, Chlorphenesin, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Triethanolamine, Caprylyl Glycol, Panthenol, Xanthan Gum, Hydroxyethylcellulose, Fragrance, Allantoin, Adenosine, Disodium EDTA, Sodium Polyacrylate, Butylene Glycol, Sodium Hyaluronate, Snail Secretion Filtrate, Beta-Glucan, Pentylene Glycol, Soy Isoflavones, Pueraria Lobata Root Extract, Pueraria Mirifica Root Extract, Polygonum Cuspidatum Root Extract, Cimicifuga Racemosa Root Extract, Sodium Hyaluronate Crosspolymer, Hydrolyzed Hyaluronic Acid, Trifolium Pratense (Clover) Flower Extract, Punica Granatum Fruit Extract, Angelica Polymorpha Sinensis Root Extract, CI 42090, Hyaluronic Acid, Sodium Acetylated Hyaluronate, Hydroxypropyltrimonium Hyaluronate, Hydrolyzed Sodium Hyaluronate.');
