INSERT INTO `products` (`id`, `product_id`, `sku`, `name`, `short_name`, `category_id`, `category_name`, `price`, `original_price`, `discount`, `badge`, `rating`, `sold`, `stock`, `brand`, `description`, `seo_tags`, `shopee_url`, `tiktok_url`, `is_flash_sale`, `flash_sale_percent`, `is_active`, `created_at`, `updated_at`, `features_vn`, `features_en`, `footer_info`, `production_year`, `clearance_price`, `daily_sale_price`, `campaign_price`, `off_platform_price`, `warranty_data`, `youtube_url`, `origin`, `volume`, `ingredients`) VALUES (38, 'kem-chong-nang-nang-tone-spf-50-pa-water-full-sun-', 'KCNCN.SL', 'Kem Chống Nắng Nâng Tone SPF 50+ PA++++ WATER-FULL SUN CREAM SL LEPORTS Lâu Trôi Kháng Nước Hàn Quốc', NULL, NULL, 'Kem chống nắng da dầu/khô', 378000, 420000, 10, 'BestSeller', '5', 261, 99, 'SL LEPORTS', 'Kem Chống Nắng Nâng Tone SPF 50+ PA++++ SL LEPORTS WATER-FULL SUN CREAM Lâu Trôi Kháng Nước\n✨ Vì sao bạn sẽ thích?\nMột tuýp kem - nhiều công năng: chống nắng phổ rộng, nâng tone tự nhiên, cấp ẩm mướt mịn và bám lâu suốt ngày dài. Công thức ""Water-Full"" giàu nước, mát lạnh tức thì, không bí da, không vệt trắng. Đi biển, chơi thể thao, đi học hay đi làm văn phòng đều dùng được.\n\n✨ ƯU ĐIỂM NỔI BẬT\n- Chỉ số chống nắng cao SPF 50+ / PA++++, bảo vệ da khỏi tia UVA - UVB suốt ngày dài\n- Giảm kích ứng hiệu quả nhờ kết hợp màng lọc vật lý + hóa học, dịu nhẹ\n- Kháng nước - kháng mồ hôi, lâu trôi khi bơi lội, vận động ngoài trời\n- Nâng tone tức thì, da sáng tự nhiên, che mờ khuyết điểm nhẹ\n- Kết cấu mỏng nhẹ, thẩm thấu nhanh, không bóng dầu, không vón mảng\n- Cấp ẩm sâu, làm dịu da nhờ chiết xuất thực vật và dịch lên men\n\n✨ THÔNG TIN THƯƠNG HIỆU\nSMILE LEADER (스마일리더) là thương hiệu mỹ phẩm đến từ Hàn Quốc, được ""bão review"" từ TOP người nổi tiếng Hàn Quốc chia sẻ trên Coupang, Olive Young, TOP tìm kiếm trên Naver. Nổi tiếng với các dòng sản phẩm chăm sóc da chuyên sâu và công nghệ Hàn Quốc hiện đại. Sản phẩm được sản xuất bởi SL Cosmetic Co., Ltd, được nhập khẩu và phân phối chính hãng độc quyền bởi GC Nature tại Việt Nam.\n\n✨ THÀNH PHẦN CHÍNH & CÔNG DỤNG\nBộ lọc UV phổ rộng: Ethylhexyl Methoxycinnamate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Titanium Dioxide, Zinc Oxide, Isoamyl p-Methoxycinnamate, Terephthalylidene Dicamphor Sulfonic Acid (Mexoryl SX)\nSodium Hyaluronate: cấp & giữ ẩm sâu, da căng mịn\nLactobacillus/Soybean Ferment Extract: dịch lên men giúp da khỏe, mượt\nMilk Protein Extract: nuôi dưỡng da mềm mại\nTocopherol & Tocopheryl Acetate (Vitamin E): chống oxy hóa, làm dịu\nChiết xuất Hinoki, Quế, Oregano, Rau sam, Vỏ liễu trắng, Hoàng cầm: làm dịu da, giảm cảm giác khó chịu do nắng - gió\nLimnanthes Alba (Meadowfoam) Seed Oil: khóa ẩm, da mướt không bí\n\n✨ HƯỚNG DẪN SỬ DỤNG\nDùng ở bước cuối cùng trong chu trình dưỡng da buổi sáng, sau kem dưỡng và trước trang điểm.\nLấy lượng vừa đủ (khoảng 1 đồng xu), chấm 5 điểm lên mặt và cổ.\nTán đều theo chiều từ trong ra ngoài, vỗ nhẹ để kem thẩm thấu.\nThoa lại sau mỗi 2 - 3 giờ khi hoạt động ngoài trời, đi biển hoặc đổ nhiều mồ hôi.\nTẩy trang sạch vào cuối ngày để da luôn thông thoáng.\n\n✨ HƯỚNG DẪN BẢO QUẢN\nĐậy kín nắp sau khi dùng, để nơi khô ráo, thoáng mát\nTránh ánh nắng trực tiếp và nhiệt độ cao trên 30°C\nĐể xa tầm tay trẻ em\nNên dùng hết trong 12 tháng kể từ ngày mở nắp\n\n#kemchongnang #kemchongnangnangtone #SLLEPORTS #WaterFullSunCream #SPF50 #PAplus4 #kemchongnanghanquoc #kemchongnanglautroi #kemchongnangkhangnuoc #chongnangdiboi #chongnangdibien #kemchongnangchodanhaycam #myphamhan #SLcosmetics #suncreamkorea #kbeauty #skincare #chongnangphoroong', '{"title":"Kem Chống Nắng Nâng Tone SPF 50+ PA++++ WATER-FULL SUN CREAM SL LEPORTS Lâu Trôi Kháng Nước Hàn Quốc","desc":"Kem Chống Nắng Nâng Tone SPF 50+ PA++++ WATER-FULL SUN CREAM SL LEPORTS Lâu Trôi Kháng Nước Hàn Quốc\\n- Chỉ số chống nắng cao SPF 50+ / PA++++, bảo vệ da khỏi tia UVA - UVB suốt ngày dài\\n- Giảm kích ứng hiệu quả nhờ kết hợp màng lọc vật lý + hóa học, dịu nhẹ\\n- Kháng nước - kháng mồ hôi, lâu trôi khi bơi lội, vận động ngoài trời\\n- Nâng tone tức thì, da sáng tự nhiên, che mờ khuyết điểm nhẹ\\n- Kết cấu mỏng nhẹ, thẩm thấu nhanh, không bóng dầu, không vón mảng\\n- Cấp ẩm sâu, làm dịu da nhờ chiết xuất thực vật và dịch lên men","keywords":"kem chống nắng, chống nắng, nâng tone, kháng nước, lâu trôi, chống nắng phổ rộng, kem chống nắng hàn, smile leader, kem sl leports, water full sun, spf 50, chống nắng vật lý, chống nắng hóa học, chống nắng thể thao, da nhạy cảm, cấp ẩm, kem chống nắng nâng tone, kem chống nắng lâu trôi, kem chống nắng kháng nước, kem chống nắng smile leader, kem chống nắng sl leports, kem chống nắng water full, kem chống nắng hàn quốc, chống nắng nâng tone tự nhiên, kem chống nắng đi biển, kem chống nắng chơi thể thao, kem chống nắng spf 50, kem chống nắng không bóng dầu, kem chống nắng cho da nhạy cảm, kemchongnang, kemchongnangnangtone, SLLEPORTS, WaterFullSunCream, SPF50, PAplus4, kemchongnanghanquoc, kemchongnanglautroi, kemchongnangkhangnuoc, chongnangdiboi, chongnangdibien, kemchongnangchodanhaycam, myphamhan, SLcosmetics, suncreamkorea, kbeauty, skincare, chongnangphoroong"}', 'https://s.shopee.vn/5VTS9HQQCH', 'https://vt.tiktok.com/ZS965TVL67fNd-U0wqq/', 1, 1, 1, '2026-07-03 19:08:15', '2026-07-27 16:39:17', 'Kem Chống Nắng Nâng Tone SPF 50+ PA++++ WATER-FULL SUN CREAM SL LEPORTS Lâu Trôi Kháng Nước Hàn Quốc\n- Chỉ số chống nắng cao SPF 50+ / PA++++, bảo vệ da khỏi tia UVA - UVB suốt ngày dài\n- Giảm kích ứng hiệu quả nhờ kết hợp màng lọc vật lý + hóa học, dịu nhẹ\n- Kháng nước - kháng mồ hôi, lâu trôi khi bơi lội, vận động ngoài trời\n- Nâng tone tức thì, da sáng tự nhiên, che mờ khuyết điểm nhẹ\n- Kết cấu mỏng nhẹ, thẩm thấu nhanh, không bóng dầu, không vón mảng\n- Cấp ẩm sâu, làm dịu da nhờ chiết xuất thực vật và dịch lên men', 'Ethylhexyl Methoxycinnamate, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Titanium Dioxide, Zinc Oxide, Limnanthes Alba (Meadowfoam) Seed Oil, Lactobacillus/Soybean Ferment Extract, Milk Protein Extract, Portulaca Oleracea Extract, Sodium Hyaluronate, Tocopherol.', NULL, 2026, 0, 378000, 0, 0, '', NULL, 'Hàn Quốc', '60ml', 'Water, Ethylhexyl Methoxycinnamate, Butylene Glycol, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine, Titanium Dioxide, Terephthalylidene Dicamphor Sulfonic Acid, C12-15 Alkyl Benzoate, Cetearyl Alcohol, Isoamyl p-Methoxycinnamate, Zinc Oxide, 1,2-Hexanediol, Cetyl PEG/PPG-10/1 Dimethicone, Dimethicone, Talc, C12-16 Alcohols, Glyceryl Stearate, Glyceryl Stearate SE, PEG-100 Stearate, Polyacrylamide, Polysorbate 20, Sorbitan Sesquioleate, Stearyl Behenate, Tocopheryl Acetate, Tromethamine, Acrylates/C10-30 Alkyl Acrylate Crosspolymer, Aluminum Hydroxide, C13-14 Isoparaffin, Chlorphenesin, Hydrogenated lecithin, Isostearic Acid, Laureth-7, Limnanthes Alba (Meadowfoam) Seed Oil, Palmitic Acid, Polyhydroxystearic Acid, Stearic Acid, Xanthan Gum, Ethylhexylglycerin, Sorbitan Trioleate, Chamaecyparis Obtusa Leaf Extract, Cinnamomum Cassia Bark Extract, Disodium EDTA, Fragrance, Lactobacillus/Soybean Ferment Extract, Milk Protein Extract, Origanum Vulgare Leaf Extract, Portulaca Oleracea Extract, Salix Alba (Willow) Bark Extract, Scutellaria Baicalensis Root Extract, Sodium Hyaluronate, Tocopherol.');
