INSERT INTO `settings` (`id`, `key`, `value`, `updated_at`) VALUES (13, 'page_about', '{"title":"Giới Thiệu","desc":"GC Nature - Thương hiệu hóa mỹ phẩm nhập khẩu chính hãng Hàn Quốc","sections":[],"tabsConfig":null,"introTitle":null,"introText":null,"popupDelay":5,"popupOpacity":60,"popupWidth":500,"updatedAt":"2026-07-27T12:11:16.756Z","seoTitle":"Giới Thiệu GC Nature - Mỹ Phẩm Chính Hãng Nội Địa Hàn Quốc","seoDesc":"GC Nature - đơn vị phân phối độc quyền mỹ phẩm nội địa Hàn Quốc chính hãng uy tín tại Việt Nam. Chúng tôi tự hào mang đến các giải pháp chăm sóc da chuyên sâu, an toàn tuyệt đối với công nghệ K-Beauty tiên tiến. Cung cấp đa dạng sản phẩm chuẩn y khoa: từ tinh chất PDRN cá hồi tái tạo, mặt nạ Cica phục hồi cho da mỏng yếu, đến kem chống nắng bảo vệ toàn diện. Sản phẩm thuộc top đầu Olive Young, sản xuất bởi CELLCOCO. Đồng hành cùng GC Nature để đánh thức vẻ đẹp nguyên bản rạng rỡ!","seoKeywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicacomplex, serum HA, serum hyaluronic, c