INSERT INTO `settings` (`id`, `key`, `value`, `updated_at`) VALUES (14, 'page_faq', '{"title":"Câu Hỏi Thường Gặp","desc":"Câu hỏi thường gặp của khách hàng","sections":[],"tabsConfig":null,"introTitle":null,"introText":null,"popupDelay":5,"popupOpacity":60,"popupWidth":500,"updatedAt":"2026-07-27T12:12:43.177Z","seoTitle":"Q&A GC Nature","seoDesc":"Hỏi đáp từ GC Nature giúp bạn giải đáp mọi thắc mắc về mỹ phẩm Hàn Quốc chính hãng. Tại đây, chúng tôi hướng dẫn chi tiết cách xây dựng routine skincare phục hồi, cách sử dụng mặt nạ Cica, tinh chất PDRN cá hồi, kem chống nắng cho da nhạy cảm an toàn nhất. Bên cạnh đó, khách hàng cũng dễ dàng tra cứu các chính sách đổi trả, vận chuyển và cam kết độc quyền. Truy cập ngay để chăm sóc làn da khoa học, hiệu quả chuẩn K-Beauty cùng chuyên gia GC Nature!\\"","seoKeywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicacomplex, serum HA, serum hyaluronic, cấp nước đa tầng, căng bóng da, serum dưỡng ẩm, dưỡng ẩm sâu, tinh chất HA, tinh chất ốc sên, da căng