INSERT INTO `settings` (`id`, `key`, `value`, `updated_at`) VALUES (17, 'page_policy_mua-hang', '{"title":"Chính Sách Mua Hàng","desc":"GCnature thông báo quy trình mua hàng và chăm sóc khách hàng","sections":[],"tabsConfig":null,"introTitle":null,"introText":null,"popupDelay":5,"popupOpacity":60,"popupWidth":500,"updatedAt":"2026-07-27T12:17:04.636Z","seoTitle":"GC Nature - Chính Sách Mua Hàng","seoDesc":"Chính sách mua hàng GC Nature quy định rõ ràng, minh bạch nhằm đảm bảo quyền lợi tối đa cho khách hàng khi mua sắm mỹ phẩm Hàn Quốc chính hãng. Tìm hiểu chi tiết các quy định về hướng dẫn đặt hàng, phương thức thanh toán an toàn, quy trình giao nhận, bảo mật thông tin cá nhân, chính sách bảo hành, đổi trả và hoàn tiền nhanh chóng. Chúng tôi cam kết mang đến trải nghiệm mua sắm tiện lợi, an tâm tuyệt đối với 100% sản phẩm nội địa Hàn chuẩn K-Beauty. Xem ngay chi tiết để an tâm mua sắm!","seoKeywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicacomplex, serum HA, serum hyaluronic, cấp nước 