INSERT INTO `settings` (`id`, `key`, `value`, `updated_at`) VALUES (18, 'page_policy_bao-mat', '{"title":"Chính Sách Bảo Mật Thông Tin","desc":"GCnature cam kết bảo mật thông tin khách hàng","sections":[],"tabsConfig":null,"introTitle":null,"introText":null,"popupDelay":5,"popupOpacity":60,"popupWidth":500,"updatedAt":"2026-07-27T12:17:41.339Z","seoTitle":"GC Nature - Chính Sách Bảo Mật Thông Tin","seoDesc":"Chính sách bảo mật thông tin GC Nature cam kết bảo vệ tuyệt đối dữ liệu cá nhân của khách hàng khi mua sắm mỹ phẩm Hàn Quốc chính hãng. Chúng tôi quy định rõ ràng về mục đích thu thập, cách thức sử dụng và lưu trữ thông tin an toàn. Với hệ thống bảo mật công nghệ cao, mọi dữ liệu thanh toán và giao dịch của bạn luôn được mã hóa nghiêm ngặt, tránh mọi rủi ro rò rỉ. Khách hàng hoàn toàn an tâm tận hưởng trải nghiệm mua sắm K-Beauty cao cấp. Xem ngay chi tiết quyền lợi riêng tư của bạn!","seoKeywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicacomplex, serum HA, serum hyaluronic, cấp nước