INSERT INTO `settings` (`id`, `key`, `value`, `updated_at`) VALUES (19, 'page_policy_thanh-toan', '{"title":"Chính Sách Thanh Toán","desc":"GCnature thông báo chính sách thanh toán","sections":[],"tabsConfig":null,"introTitle":null,"introText":null,"popupDelay":5,"popupOpacity":60,"popupWidth":500,"updatedAt":"2026-07-27T12:18:12.807Z","seoTitle":"GC Nature - Chính Sách Thanh Toán","seoDesc":"Chính sách thanh toán GC Nature cung cấp các phương thức giao dịch an toàn, linh hoạt và tiện lợi nhất cho khách hàng khi mua sắm mỹ phẩm Hàn Quốc chính hãng. Chúng tôi hỗ trợ đa dạng hình thức thanh toán từ nhận hàng trả tiền mặt (COD), chuyển khoản ngân hàng đến thanh toán qua thẻ tín dụng và ví điện tử. Mọi giao dịch đều được mã hóa bảo mật tuyệt đối, đảm bảo an toàn thông tin tài chính. Tìm hiểu ngay chi tiết quy định để có trải nghiệm mua sắm K-Beauty nhanh chóng và an tâm tuyệt đối!","seoKeywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicacomplex, serum HA, serum hyaluronic, cấp nước đa tầng, c