INSERT INTO `settings` (`id`, `key`, `value`, `updated_at`) VALUES (20, 'page_policy_khach-hang-than-thiet', '{"title":"Chính Sách Khách Hàng Thân Thiết","desc":"Chương trình khách hàng thân thiết","sections":[],"tabsConfig":null,"introTitle":null,"introText":null,"popupDelay":5,"popupOpacity":60,"popupWidth":500,"updatedAt":"2026-07-27T12:18:53.638Z","seoTitle":"GC Nature - Chính Sách Khách Hàng Thân Thiết","seoDesc":"Chính sách khách hàng thân thiết GC Nature mang đến hàng ngàn đặc quyền hấp dẫn dành riêng cho hội viên mua sắm mỹ phẩm Hàn Quốc chính hãng. Tham gia ngay chương trình tích điểm đổi quà, thăng hạng thành viên để nhận voucher giảm giá siêu hời, quà tặng sinh nhật độc quyền và ưu đãi miễn phí vận chuyển. Chúng tôi luôn trân trọng và tri ân sự đồng hành của bạn trên hành trình chăm sóc làn da chuẩn K-Beauty. Đăng ký tài khoản ngay hôm nay để tận hưởng trọn vẹn các đặc quyền VIP từ hệ thống!","seoKeywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicacomplex, serum HA, serum hyalu