INSERT INTO `settings` (`id`, `key`, `value`, `updated_at`) VALUES (21, 'page_policy_khieu-nai', '{"title":"Chính Sách Xử Lý Khiếu Nại","desc":"GC Nature cam kết luôn hỗ trợ và bảo vệ quyền lợi khách hàng","sections":[],"tabsConfig":null,"introTitle":null,"introText":null,"popupDelay":5,"popupOpacity":60,"popupWidth":500,"updatedAt":"2026-07-27T12:19:25.624Z","seoTitle":"GC Nature - Chính Sách Xử Lý Khiếu Nại","seoDesc":"Chính sách xử lý khiếu nại GC Nature luôn đặt quyền lợi của khách hàng lên hàng đầu khi mua sắm mỹ phẩm Hàn Quốc chính hãng. Chúng tôi cam kết tiếp nhận và giải quyết mọi phản ánh liên quan đến chất lượng sản phẩm, dịch vụ tư vấn, quy trình giao nhận hay lỗi từ nhà sản xuất một cách nhanh chóng, minh bạch và công bằng nhất. Với quy trình hỗ trợ chuyên nghiệp, đội ngũ chăm sóc khách hàng luôn sẵn sàng lắng nghe để mang lại sự hài lòng tuyệt đối cho bạn khi trải nghiệm làm đẹp chuẩn K-Beauty.","seoKeywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicacomplex, serum HA, serum 