INSERT INTO `settings` (`id`, `key`, `value`, `updated_at`) VALUES (23, 'page_policy_affiliate', '{"title":"Chương Trình Affiliate","desc":"Khám phá chương trình đồng hành với doanh nghiệp tiếp thị sản phẩm","sections":[],"tabsConfig":null,"introTitle":null,"introText":null,"popupDelay":5,"popupOpacity":60,"popupWidth":500,"updatedAt":"2026-07-27T12:20:51.335Z","seoTitle":"GC Nature - Chương Trình Affiliate - Tiếp Thị Liên Kết Hóa Mỹ Phẩm","seoDesc":"Chương trình Affiliate tiếp thị liên kết hóa mỹ phẩm GC Nature mang đến cơ hội kiếm tiền online dễ dàng với mức hoa hồng vô cùng hấp dẫn. Tham gia mạng lưới đối tác của chúng tôi để quảng bá và phân phối các dòng mỹ phẩm Hàn Quốc chính hãng chuẩn K-Beauty. Không cần bỏ vốn, không lo tồn kho, hệ thống cung cấp sẵn tài liệu marketing chuyên nghiệp và theo dõi đơn hàng minh bạch. Đăng ký tài khoản ngay hôm nay để bứt phá thu nhập thụ động cùng hàng ngàn sản phẩm làm đẹp uy tín hàng đầu!","seoKeywords":"serum cica, serum rau má, tinh chất cica, tinh chất rau má, serum phục hồi, phục hồi da, serum dịu da, da nhạy cảm, cấp ẩm sâu, mỹ phẩm Hàn, GC nature, giảm kích ứng, mờ thâm mụn, tinh chất B5, dưỡng sáng da, serum cấp ẩm, tinh chất cấp ẩm, serum lành tính, serum cica phục hồi da, serum rau má giảm kích ứng, tinh chất cica dịu da, tinh chất rau má Hàn Quốc, serum phục hồi da yếu, serum phục hồi sau mụn, serum dưỡng da nhạy cảm, serum cấp ẩm căng mọng, mỹ phẩm Hàn Quốc chính hãng, tinh chất giảm đỏ rát, serum mờ thâm sau mụn, cica complex serum gc nature, serum rau má cấp ẩm, serum dịu da mẩn đỏ, serumcica, cicacomplexserum, serumrauma, anely, anelycica, serumhanquoc, serumphuchoida, serumdanhaycam, serumcapam, serumlamdiu, serumgiamkichung, cicaserum, myphamhanquoc, serumduda, serumdumun, anelyserum, seumlanhtinh, serumcentella, rauma, capamsau, myphamhan, gcnature, serummotham, serumcicaHanquoc, tinhchatraumaHanquoc, serumphuchoidayeu, serumduongdanhaycam, myphamhanquocchinhhang, tinhchatgiamdorat, serummothamsaumun, cicaco